// Builds src/lib/plate-map-land.mjs: simplified land outlines for the Plate Boundaries Map.
// Source: the world-atlas npm package (ISC license), which redistributes Natural Earth's 1:50m land
// polygons (public domain, naturalearthdata.com). Run with `npm run map-land` after changing the settings
// below; the generated file is committed, so the site never needs world-atlas to build.
import fs from 'node:fs';
import { createRequire } from 'node:module';

const TOLERANCE = 0.22; // degrees: points closer than this to the simplified outline are dropped
const MIN_AREA = 0.35; // square degrees: smaller islands are left out
const SOUTH = -78; // nothing below this latitude is drawn
const require = createRequire(import.meta.url);
const topology = JSON.parse(fs.readFileSync(require.resolve('world-atlas/land-50m.json'), 'utf8'));

// Decode the TopoJSON arcs (delta-encoded, quantized) into longitude and latitude.
const { scale, translate } = topology.transform;
const arcs = topology.arcs.map(arc => {
  let x = 0, y = 0;
  return arc.map(([dx, dy]) => { x += dx; y += dy; return [x * scale[0] + translate[0], y * scale[1] + translate[1]]; });
});
const ring = indexes => indexes.flatMap((i, n) => {
  const points = i < 0 ? [...arcs[~i]].reverse() : arcs[i];
  return n ? points.slice(1) : points;
});
const polygons = topology.objects.land.geometries.flatMap(g => (g.type === 'Polygon' ? [g.arcs] : g.arcs));
// Outer rings only: lakes and inland seas inside the land are not needed at this scale.
// A ring that crosses the 180° line jumps from one edge of the map to the other. Unwrap it so that it
// runs on past 180° instead (the eastern tip of Russia ends near 190°); the map draws the land once more
// a whole turn to the west and to the east, so the overhang shows up on the other side.
const unwrap = pts => {
  let shift = 0;
  const out = pts.map(([x, y], i) => {
    if (i > 0) { const dx = x - pts[i - 1][0]; if (dx > 180) shift -= 360; else if (dx < -180) shift += 360; }
    return [x + shift, y];
  });
  const min = Math.min(...out.map(p => p[0]));
  return min < -180 ? out.map(([x, y]) => [x + 360, y]) : out;
};
const rings = polygons.map(polygon => unwrap(ring(polygon[0])));

const area = pts => Math.abs(pts.reduce((sum, [x, y], i) => { const [nx, ny] = pts[(i + 1) % pts.length]; return sum + x * ny - nx * y; }, 0)) / 2;
// Douglas–Peucker line simplification.
function simplify(pts, tolerance) {
  const keep = new Uint8Array(pts.length);
  keep[0] = keep[pts.length - 1] = 1;
  const stack = [[0, pts.length - 1]];
  while (stack.length) {
    const [a, b] = stack.pop();
    const [ax, ay] = pts[a], [bx, by] = pts[b];
    const dx = bx - ax, dy = by - ay, len = Math.hypot(dx, dy);
    let worst = 0, at = -1;
    for (let i = a + 1; i < b; i++) {
      const d = len ? Math.abs(dy * (pts[i][0] - ax) - dx * (pts[i][1] - ay)) / len : Math.hypot(pts[i][0] - ax, pts[i][1] - ay);
      if (d > worst) { worst = d; at = i; }
    }
    if (worst > tolerance) { keep[at] = 1; stack.push([a, at], [at, b]); }
  }
  return pts.filter((_, i) => keep[i]);
}
const round = v => Math.round(v * 10) / 10;
const land = rings
  .filter(pts => area(pts) >= MIN_AREA)
  .map(pts => {
    // Simplify each closed ring in two halves so that its start point is not special.
    const half = Math.floor(pts.length / 2);
    const out = [...simplify(pts.slice(0, half + 1), TOLERANCE), ...simplify(pts.slice(half), TOLERANCE).slice(1)];
    return out.map(([x, y]) => [round(x), round(Math.max(SOUTH, y))]).filter((p, i, all) => i === 0 || p[0] !== all[i - 1][0] || p[1] !== all[i - 1][1]);
  })
  .filter(pts => pts.length >= 4 && area(pts) >= MIN_AREA * 0.6)
  .sort((a, b) => area(b) - area(a));

const points = land.reduce((sum, pts) => sum + pts.length, 0);
const body = land.map(pts => `  [${pts.map(([x, y]) => `[${x},${y}]`).join(',')}],`).join('\n');
fs.writeFileSync(new URL('../src/lib/plate-map-land.mjs', import.meta.url), `// Generated by scripts/plate-map-land.mjs (npm run map-land). Do not edit by hand.
// Simplified land outlines, as rings of [longitude, latitude] in degrees, largest first. A ring that crosses
// the 180° line carries on past 180 (up to about 190) so that it stays in one piece.
// Data: Natural Earth 1:50m land (public domain), via the world-atlas npm package (ISC license).
// ${land.length} outlines, ${points} points; simplified to ${TOLERANCE}°, islands under ${MIN_AREA} square degrees left out.
export const LAND = [
${body}
];
`);
console.log(`${rings.length} rings in the source; wrote ${land.length} outlines with ${points} points.`);
